        const filterCount=Number(industry!=='all')+Number(!!stateFilter);
        toolbar.innerHTML=`<div class="jobs-browse-controls"><div class="jobs-search-row"><label class="jobs-search-field"><span class="jobs-sr-only">${esc(t('jobs.board.browse.searchLabel'))}</span><input type="search" class="field" id="jobsSearch" placeholder="${esc(t('jobs.board.browse.searchPlaceholder'))}" value="${esc(query)}"></label><button type="button" class="btn jobs-filter-toggle${filterCount?' is-filtered':''}" id="jobsToggleFilters" data-jobs-action="toggle-filters" aria-label="${esc(t('jobs.board.browse.filterLabel'))}" title="${esc(t('jobs.board.browse.filterLabel'))}" aria-expanded="${filtersOpen}" aria-controls="jobsRefinements"><span>${esc(po('Bộ lọc','Filters'))}</span>${filterCount?`<span class="jobs-filter-count">${filterCount}</span>`:''}</button></div><div class="jobs-filter-row" role="group" aria-label="${esc(t('jobs.board.browse.filterLabel'))}">${['all','hiring','seeking','saved'].map(value=>`<button type="button" class="filter-chip${filter===value?' active':''}" aria-pressed="${filter===value}" data-jobs-filter="${value}">${esc(value==='saved'?po('★ Đã lưu','★ Saved'):t('jobs.board.browse.filters.'+({all:'All',hiring:'Hiring',seeking:'Seeking'})[value]))}</button>`).join('')}</div></div><div class="jobs-refinements" id="jobsRefinements"${filtersOpen?'':' hidden'}><label class="jobs-field"><span>${esc(po('Ngành nghề','Industry'))}</span><select class="select" id="jobsIndustryFilter">${industries.map(([value,label])=>`<option value="${esc(value)}"${industry===value?' selected':''}>${esc(label)}</option>`).join('')}</select></label><label class="jobs-field"><span>${esc(t('jobs.board.browse.stateLabel'))}</span><select class="select" id="jobsStateFilter"><option value="">${esc(t('jobs.board.browse.allAreas'))}</option>${Object.entries(states).map(([code,name])=>`<option value="${esc(code)}"${stateFilter===code?' selected':''}>${esc(name)}</option>`).join('')}</select></label></div>`;
