    function select(name,label,value,options) {return `<label class="jobs-field"><span>${esc(label)}</span><select class="select" name="${name}"><option value="">${esc(t('jobs.profile.fields.choose'))}</option>${options.map(([id,text])=>`<option value="${esc(id)}"${value===id?' selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
