      return `<section class="jobs-profile-preview"><div class="jobs-profile-cover">${profile.isOpenToWork?`<span class="jobs-status open">${esc(t('jobs.preview.openToWorkBadge'))}</span>`:''}<div class="jobs-avatar">${esc(profile.displayName?.slice(0,1)||'')}</div></div><h3>${esc(profile.displayName)}</h3><p class="meta">${esc([profile.cityName,profile.stateCode].filter(Boolean).join(', ')||t('jobs.preview.noRegion'))} · ${esc(profile.experience?t('jobs.profile.options.experience.'+profile.experience):t('jobs.preview.noExperience'))}</p><span class="jobs-status">${esc(t('jobs.preview.license.'+(profile.licenseVerificationStatus||'Unverified')))}</span>${profile.bio?`<p class="jobs-profile-bio">${esc(profile.bio)}</p>`:''}<div class="chips">${(profile.skills||[]).map(skill=>`<span class="chip">${esc(typeof skill==='string'?skill:skill.names?.[language()]||skill.code)}</span>`).join('')}</div>${facts([[t('jobs.profile.fields.languages'),translated('languages','language')],[t('jobs.applications.preferredJobs'),translated('jobTypes','jobType')],[t('jobs.applications.compensation'),[translated('payTypes','payType'),profile.expectedPay].filter(Boolean).join(' · ')],[t('jobs.profile.fields.license'),profile.licenseType?t('jobs.profile.options.license.'+profile.licenseType):''],[t('jobs.board.owner.preview.phone'),profile.phone]])}${profile.portfolioImageUrls?.length?photoGrid(profile.portfolioImageUrls,'candidate'):''}</section>`;
