    function fileData(file) {return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)){reject(new Error(t('jobs.profile.validation.imageType')));return;}if(file.size>700*1024){reject(new Error(po('PNG, JPG, WebP hoặc GIF · tối đa 700 KB trong bản thử','PNG, JPG, WebP or GIF · maximum 700 KB in this demo')));return;}const reader=new FileReader();reader.onload=()=>safeImage(reader.result)?resolve(reader.result):reject(new Error(t('jobs.board.images.unreadable')));reader.onerror=()=>reject(new Error(t('jobs.board.images.unreadable')));reader.readAsDataURL(file);});}
    async function uploadFiles(control, portfolio) {
      const files=Array.from(control.files||[]);if(!files.length)return;
      const max=portfolio?9:6,current=portfolio?getProfile().portfolioImageUrls:editor?.images||[];
      if(files.length+current.length>max){toast(t('jobs.board.images.tooMany',{max}));control.value='';return;}
      control.disabled=true;
      try {
        const images=await Promise.all(files.map(fileData));
        if(!control.isConnected)return;
        if(portfolio){if(saveProfile('Portfolio',{portfolioImageUrls:[...getProfile().portfolioImageUrls,...images]}))profileStep=2;}
        else if(editor){editor.images.push(...images);editor.form.querySelector('[data-jobs-editor-images]').innerHTML=editorPhotosMarkup();}
      } catch(error) {formError(control.closest('form'),error.message);} finally {control.disabled=false;control.value='';}
    }
    function navigate(view = 'browse', context = {}) {
      if(typeof view==='object'){context=view;view=context.jobsTab||'browse';}
      if(view==='jobs')view=context.jobsTab||'browse';
      view=({Jobs:'browse',JobsMyPosts:'myPosts',JobsApplied:'applied',StaffJobProfile:'profile',jobsMyPosts:'myPosts',jobsApplied:'applied',staffJobProfile:'profile'})[view]||view;
      if(['browse','myPosts','applied','profile'].includes(view))tab=view;
      if(role()==='owner'&&['applied','profile'].includes(tab))tab='browse';
      if(context.profileRequired&&context.jobId)pendingJob=context.jobId;
      render();notifyState();
      if(context.jobId&&!context.profileRequired&&tab!=='profile')openJob(context.jobId);
      return true;
    }
    function onClick(event) {
      const target=event.target.closest?.('[data-jobs-action], button[data-jobs-tab], [data-jobs-post-status], [data-jobs-filter], [data-jobs-step], [data-template="hiring"], [data-template="seeking"], [data-open-job], [data-job-contact]');
      if(!target)return;
      event.preventDefault();event.stopImmediatePropagation();
      if(target.disabled)return;
      if(target.dataset.template)return openEditor(target.dataset.template);
      if(target.hasAttribute('data-open-job')||target.hasAttribute('data-job-contact')){const id=target.dataset.openJob||target.dataset.jobContact;adapter.navigate?.('jobs',{jobsTab:'browse'});tab='browse';render();return openJob(id);}
      if(target.dataset.jobsTab){adapter.closeDialog?.();tab=target.dataset.jobsTab;query='';render();notifyState();return;}
      if(target.dataset.jobsPostStatus){postTab=target.dataset.jobsPostStatus;render();return;}
      if(target.dataset.jobsFilter){filter=target.dataset.jobsFilter;render();return;}
      if(target.dataset.jobsStep){profileStep=Number(target.dataset.jobsStep);render();return;}
      const action=target.dataset.jobsAction,id=target.dataset.jobsId;
      if(action==='dismiss')return dismiss();
      if(action==='detail')return openJob(id);
      if(action==='save')return toggleSaved(id);
      if(action==='toggle-filters'){filtersOpen=!filtersOpen;render();document.getElementById('jobsToggleFilters')?.focus();return;}
      if(action==='apply')return requestApply(id);
      if(action==='edit')return openEditor(getJob(id)?.kind,getJob(id));
      if(action==='applicants')return openApplicants(id);
      if(action==='candidate')return openCandidate(id);
      if(action==='applicant-profile'){const application=(readState()?.applications||[]).find(row=>row.id===id);if(application)return openCandidate(application.postingId,id);return;}
      if(action==='job-chat'){const row=getJob(id);if(row&&!own(row))return chat(row.owner,id,row.title);return;}
      if(action==='application-chat'){const row=(readState()?.applications||[]).find(item=>item.id===id&&item.applicantUserId===member());if(row)return chat(row.businessName||row.ownerUserId,row.postingId,row.postingTitle);return;}
      if(action==='applicant-chat'){const row=(readState()?.applications||[]).find(item=>item.id===id);const profile=applicantProfile(id);if(profile)return chat(profile.displayName,row.postingId,row.postingTitle);return;}
      if(action==='invite-chat'){const row=(readState()?.invites||[]).find(item=>item.id===id&&(item.from===member()||item.to===member()));if(row)return chat(row.from===member()?getProfile(row.to).displayName:row.fromName,row.postingId,po('Mời phỏng vấn','Invite to interview'));return;}
      if(action==='invite-seeking')return openInvite(id);
      if(action==='invite-applicant'){const row=(readState()?.applications||[]).find(item=>item.id===id);if(row)return openInvite(row.postingId,id);return;}
      if(action==='accept-invite'||action==='decline-invite')return respondInvite(id,action==='accept-invite'?'accepted':'declined');
      if(action==='go-applied'){adapter.closeDialog?.();tab='applied';render();notifyState();return;}
      if(action==='view-application')return openApplication(id);
      if(action==='cancel-application')return confirmCancel(id);
      if(action==='confirm-cancel'){if(cancelApplication(id,Number(target.dataset.version))){adapter.closeDialog?.();tab='applied';render();}else toast(t('jobs.applications.cancelError'));return;}
      if(action==='return-job'){pendingJob=null;tab='browse';render();return openJob(id);}
      if(action==='profile-back'){profileStep=Math.max(0,profileStep-1);render();return;}
      if(action==='close-post'){const row=getJob(id);if(!own(row))return;return showDialog(t(seeking(row)?'jobs.board.myPosts.seeking.close.title':'jobs.board.myPosts.close.title'),`<p>${esc(t(seeking(row)?'jobs.board.myPosts.seeking.close.body':'jobs.board.myPosts.close.body'))}</p>`,button('dismiss','',t('common.cancel'))+button('confirm-close',id,t(seeking(row)?'jobs.board.myPosts.seeking.close.confirm':'jobs.board.myPosts.close.confirm'),true));}
      if(action==='confirm-close'){if(closeJob(id)){adapter.closeDialog?.();toast(t('jobs.board.myPosts.close.success'));}return;}
      if(action==='map')return openMap(id);
      if(['image','image-prev','image-next'].includes(action)){if(action==='image'&&id==='portfolio'){currentGallery=getProfile().portfolioImageUrls;galleryReturn=()=>{adapter.closeDialog?.();tab='profile';render();};}return showImage(action==='image'?Number(target.dataset.jobsIndex||0):Number(id));}
      if(action==='image-back')return galleryReturn?.();
      if(action==='remove-portfolio'){const profile=getProfile();profile.portfolioImageUrls.splice(Number(id),1);return saveProfile('Portfolio',profile);}
      if(action==='remove-editor-image'){if(editor){editor.images.splice(Number(id),1);editor.form.querySelector('[data-jobs-editor-images]').innerHTML=editorPhotosMarkup();}return;}
      if(action==='save-draft')return submitEditor(target.closest('form'),'draft');
      if(action==='services')return servicesDialog();
      if(action==='back-edit'){const saved=editor?.pending;if(saved)return openEditor(saved.kind,saved);return;}
      if(action==='publish'){
        const acknowledgement=document.getElementById('jobsPublishAcknowledgement');
        if(!acknowledgement?.checked){document.getElementById('jobsPublishError').textContent=t('jobs.board.owner.preview.acknowledge');acknowledgement?.focus();return;}
        const result=editor?.pending&&saveJob(editor.pending);
        if(result){editor=null;adapter.closeDialog?.();toast(po('Đã tạo bài trong bản thử.','Post created in this demo.'));}else{const error=document.getElementById('jobsPublishError');if(error)error.textContent=t('jobs.board.owner.errors.submitError');}return;
      }
      if(action==='open-pos')return adapter.navigate?.('posRecruitment',{source:'jobs',jobsTab:tab});
    }
    function onSubmit(event) {
      const form=event.target;
      if(form.id==='templateForm'&&['hiring','seeking'].includes(form.dataset.kind)){
        if(!form.dataset.jobsEnhanced)enhanceForm(form,{});
        event.preventDefault();event.stopImmediatePropagation();submitEditor(form);return;
      }
      if(!['jobsProfileForm','jobsApplicationForm','jobsInviteForm','jobsServicesForm'].includes(form.id))return;
      event.preventDefault();event.stopImmediatePropagation();
      const data=new FormData(form),values=Object.fromEntries(data.entries());
      if(form.id==='jobsProfileForm'){
        for(const key of ['languages','skills','jobTypes','payTypes'])values[key]=data.getAll(key);
        if(form.dataset.jobsProfileStep==='Portfolio')values.portfolioImageUrls=getProfile().portfolioImageUrls;
        if(saveProfile(form.dataset.jobsProfileStep,values)){profileStep=Math.min(3,profileStep+1);render();}else formError(form,t('jobs.profile.toast.saveError'));
      } else if(form.id==='jobsApplicationForm'){
        if(values.phone){const profile=getProfile();if(!saveProfile('Basic',{...profile,phone:values.phone}))return;}
        const result=apply(form.dataset.postingId,{note:values.note,sharePhone:data.has('sharePhone')});
        if(result)applicationSent(result);else formError(form,t('jobs.applications.submitError'));
      } else if(form.id==='jobsInviteForm'){
        const result=invite(form.dataset.candidateId,form.dataset.postingId,values);
        if(result){adapter.closeDialog?.();toast(po('Lời mời đã gửi','Sent invitation'));render();}else formError(form,t('jobs.profile.toast.saveError'));
      } else if(form.id==='jobsServicesForm'&&editor){
        const ids=data.getAll('services'),services=editor.serviceCatalog.filter(service=>ids.includes(String(service.id)));
        const input={...editor.pending,selectedServices:services.map(service=>({id:service.id,name:service.name}))};
        const existing=String(input.skills||'').split(/[,;]/).map(value=>value.trim()).filter(Boolean);
        input.skills=[...new Set([...existing,...services.flatMap(service=>service.skills||[service.name])])].join(', ');
        openEditor(input.kind,input);
      }
    }
    function onInput(event) {
      if(event.target.id==='jobsSearch'){
        query=event.target.value;const selection=event.target.selectionStart;render();const input=document.getElementById('jobsSearch');input?.focus();try{input?.setSelectionRange(selection,selection);}catch{}return;
      }
      if(event.target.id==='jobsServiceSearch'){const term=event.target.value.toLocaleLowerCase();document.querySelectorAll('[data-jobs-service-name]').forEach(row=>{row.hidden=!row.dataset.jobsServiceName.includes(term);});}
    }
    function onChange(event) {
      const control=event.target;
      if(control.form?.id==='templateForm'&&control.name==='salaryType'){syncSalaryFields(control.form,true);return;}
      if(control.id==='jobsIndustryFilter'){if(adapter.setIndustryFilter)adapter.setIndustryFilter(control.value);else{document.querySelectorAll('#jobIndustryFilters [data-job-industry]').forEach(option=>option.classList.toggle('active',option.dataset.jobIndustry===control.value));render();}return;}
      if(control.id==='jobsStateFilter'){stateFilter=control.value;render();return;}
      if(control.dataset.jobsPrivacy){if(!savePrivacy(control.dataset.jobsPrivacy,control.checked))control.checked=!control.checked;return;}
      if(control.hasAttribute('data-jobs-portfolio-file')){void uploadFiles(control,true);return;}
      if(control.hasAttribute('data-jobs-editor-file')){void uploadFiles(control,false);return;}
      if(control.form?.id==='jobsProfileForm'&&control.name==='stateCode'){
        const city=control.form.elements.cityName,cities=window.NEXORA_US_GEO?.cities?.[control.value]||[];
        city.innerHTML=`<option value="">${esc(t('jobs.profile.fields.choose'))}</option>`+cities.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');
      }
    }
    function onKeydown(event) {
      const dialog=document.querySelector('[data-jobs-dialog]');if(!dialog)return;
      if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();dismiss();return;}
      if(event.key==='Tab'){
        const focusable=Array.from(dialog.querySelectorAll('button:not([disabled]), a[href], input:not([disabled]), textarea:not([disabled]), select:not([disabled])')).filter(control=>!control.hidden);
        const first=focusable[0],last=focusable[focusable.length-1];
        if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
      }
    }
    function onStorage(event) {if(event.key===STORAGE_KEY||event.key===null){if(document.querySelector('[data-jobs-dialog]'))adapter.closeDialog?.();render();}}
